    2
{{- end}}
{{- /* HT813 FXO disconnect supervision. Without it a PSTN caller who hangs up first leaves the FXO off-hook and it answers 486 to every later call. Keys and meanings from Grandstream's ht813_config_1.0.19.6 template (config-template-10212026.zip), section "FXO PORT Settings" / "FXO Termination Settings" (not the FXS-side P892/P856 loop-current keys): P893 Enable Current Disconnect, P764 Current Disconnect Threshold (50-800 ms, default 100), P28101 Enable Polarity Reversal, P712 Enable PSTN Disconnect Tone Detection, P841 PSTN Disconnect Tone (f1=@,c=/ ms; UAE busy tone 400 Hz, 375 ms on / 375 ms off, level -32 dB as in Grandstream's example). The template has no silence-timeout key, so none is written. TR-069 is not touched. */}}
{{- if .Phone.FXO}}
    1
    100
    1
    1
    f1=400@-32,c=375/375;
{{- end}}
    {{xml .Time.NTP}}
{{- with .Time.TZ.POSIX}}
    {{xml .}}
    {{xml .}}
{{- end}}
{{- with .Firmware}}
    {{.Via}}
    {{xml (noscheme .Dir)}}


{{- /* P238 "Firmware Upgrade and Provisioning": 0 checks at every boot, 1 only when the firmware pre/suffix changes, so with a window a reboot does not upgrade outside it. */}}
    {{if and .Window (ne $.Phone.Family "856")}}1{{else}}0{{end}}
{{- end}}
